//! core/config_parser (ConfigParser) against the real C++: the script
//! fixtures/upstream-v1.18.2/unit/oracle/config_parser_ops.txt (generated by config_parser_ops_gen.py) is run
//! by this interpreter and, in the oracle, by oracle/config_parser.cpp against upstream's ConfigParser; the
//! outputs (fixtures/.../oracle/config_parser.txt) must be byte-identical, including every error text.
//! Same op set, same output format: see the header of oracle/config_parser.cpp.
//!
//! The oracle reads real files from a scratch directory; here the same names are served from memory through
//! `ConfigParser::set_include_reader` (the port does no file IO). Paths are normalised like a file system
//! would ("//", "./", "dir/../"). warnUnusedKeys's logger (NULL in the oracle) is the `log` crate here: the
//! test also checks that every message written to `out` was logged too.

#![allow(clippy::needless_range_loop, clippy::manual_range_contains)]

#[macro_use]
mod common;

use std::cell::RefCell;
use std::collections::BTreeMap;
use std::collections::BTreeSet;
use std::fmt::Write as _;
use std::rc::Rc;

use common::Cases;
use common::compare_lines;
use common::fixture;
use katago_core::core::config_parser::ConfigFileReader;
use katago_core::core::config_parser::ConfigParser;
use katago_core::core::global::KataError;

// ===================================================================== log capture (the oracle passes a NULL logger)

struct CaptureLogger;

thread_local! {
  static LOGGED: RefCell<Vec<String>> = const { RefCell::new(Vec::new()) };
}

impl log::Log for CaptureLogger {
  fn enabled(&self, _: &log::Metadata) -> bool {
    true
  }
  fn log(&self, record: &log::Record) {
    if record.target().starts_with("katago_core") {
      LOGGED.with(|l| l.borrow_mut().push(format!("{}", record.args())));
    }
  }
  fn flush(&self) {}
}

static LOGGER: CaptureLogger = CaptureLogger;

fn install_logger() {
  // set_logger fails if another test of this binary already did it: the logger is the same one.
  let _ = log::set_logger(&LOGGER);
  log::set_max_level(log::LevelFilter::Info);
}

// ===================================================================== script helpers (same as the oracle's)

fn esc(s: &str) -> String {
  let mut r = String::new();
  for &c in s.as_bytes() {
    if c == b'\\' {
      r.push_str("\\\\");
    } else if c == b'\n' {
      r.push_str("\\n");
    } else if c == b'\r' {
      r.push_str("\\r");
    } else if c == b'\t' {
      r.push_str("\\t");
    } else if c < 0x20 || c >= 0x7f {
      write!(r, "\\x{:02x}", c).unwrap();
    } else {
      r.push(c as char);
    }
  }
  r
}

fn unesc(s: &str) -> String {
  let b = s.as_bytes();
  let mut r: Vec<u8> = Vec::new();
  let mut i = 0;
  while i < b.len() {
    if b[i] != b'\\' {
      r.push(b[i]);
      i += 1;
      continue;
    }
    i += 1;
    match b[i] {
      b'n' => r.push(b'\n'),
      b'r' => r.push(b'\r'),
      b't' => r.push(b'\t'),
      b'\\' => r.push(b'\\'),
      b'x' => {
        r.push(u8::from_str_radix(&s[i + 1..i + 3], 16).unwrap());
        i += 2;
      }
      _ => panic!("bad escape in script: {}", s),
    }
    i += 1;
  }
  String::from_utf8(r).expect("script strings are valid UTF-8")
}

fn q(s: &str) -> String {
  format!("[{}]", esc(s))
}

fn dbits(x: f64) -> String {
  format!("{:016X}", x.to_bits())
}
fn fbits(x: f32) -> String {
  format!("{:08X}", x.to_bits())
}

fn split_on(s: &str, d: char) -> Vec<String> {
  if s.is_empty() {
    return Vec::new();
  }
  s.split(d).map(|x| x.to_string()).collect()
}

fn parse_kvs(s: &str) -> BTreeMap<String, String> {
  let mut m = BTreeMap::new();
  for item in split_on(s, ',') {
    match item.find('=') {
      Some(p) => m.insert(item[..p].to_string(), item[p + 1..].to_string()),
      None => m.insert(item.clone(), String::new()),
    };
  }
  m
}

fn to_set(s: &str) -> BTreeSet<String> {
  split_on(s, ',').into_iter().collect()
}

fn parse_int(s: &str) -> i32 {
  match s {
    "lowest" => i32::MIN,
    "max" => i32::MAX,
    _ => s.parse::<i64>().unwrap() as i32,
  }
}
fn parse_int64(s: &str) -> i64 {
  match s {
    "lowest" => i64::MIN,
    "max" => i64::MAX,
    _ => s.parse().unwrap(),
  }
}
fn parse_uint64(s: &str) -> u64 {
  match s {
    "lowest" => 0,
    "max" => u64::MAX,
    _ => s.parse().unwrap(),
  }
}
fn parse_float(s: &str) -> f32 {
  match s {
    "lowest" => f32::MIN,
    "max" => f32::MAX,
    _ => f32::from_bits(u32::from_str_radix(s, 16).unwrap()),
  }
}
fn parse_double(s: &str) -> f64 {
  match s {
    "lowest" => f64::MIN,
    "max" => f64::MAX,
    _ => f64::from_bits(u64::from_str_radix(s, 16).unwrap()),
  }
}

fn info(c: &ConfigParser) -> String {
  let u = c.unused_keys();
  let mut unused = String::new();
  for i in 0..u.len() {
    if i > 0 {
      unused.push(',');
    }
    unused.push_str(&u[i]);
  }
  format!("file={} contents={} kv={} unused={}", q(&c.get_file_name()), q(&c.get_contents()), q(&c.get_all_key_vals()), q(&unused))
}

// ===================================================================== the in-memory file system

type Files = Rc<RefCell<BTreeMap<String, String>>>;

/// What the OS does to a path before opening it: collapse "//" and "./", resolve "dir/../".
/// None if ".." climbs above the start.
fn normalize(path: &str) -> Option<String> {
  let mut parts: Vec<&str> = Vec::new();
  for p in path.split('/') {
    if p.is_empty() || p == "." {
      continue;
    }
    if p == ".." {
      parts.pop()?;
      continue;
    }
    parts.push(p);
  }
  if parts.is_empty() {
    return None;
  }
  Some(parts.join("/"))
}

fn make_reader(files: &Files) -> ConfigFileReader {
  let files = files.clone();
  Rc::new(move |path: &str| -> Result<String, KataError> {
    // FileUtils::open: a path that does not name an existing file cannot be opened
    let found = match normalize(path) {
      Some(n) if !path.ends_with('/') => files.borrow().get(&n).cloned(),
      _ => None,
    };
    match found {
      Some(content) => Ok(content),
      None => Err(KataError::IOError(format!("Could not open file {} - does not exist or invalid permissions?", path))),
    }
  })
}

// ===================================================================== the interpreter

fn kind(e: &KataError) -> &'static str {
  match e {
    KataError::ConfigParsingError(_) => "ConfigParsingError",
    KataError::IOError(_) => "IOError",
    KataError::StringError(_) => "StringError",
    other => panic!("unexpected error type {:?}", other),
  }
}

fn run(script: &str, cases: &mut Cases) -> String {
  install_logger();
  let files: Files = Rc::new(RefCell::new(BTreeMap::new()));
  let reader = make_reader(&files);
  let mut cfgs: BTreeMap<String, ConfigParser> = BTreeMap::new();
  let mut out = String::new();

  let mut lineno = 0;
  for line in script.split('\n') {
    lineno += 1;
    if line.is_empty() || line.starts_with('#') {
      continue;
    }
    let mut f: Vec<String> = line.split('\t').map(|x| x.to_string()).collect();
    for i in 1..f.len() {
      f[i] = unesc(&f[i]);
    }
    let op = f[0].clone();
    cases.ran();
    write!(out, "{} {}", lineno, op).unwrap();
    if f.len() > 1 && op != "file" && op != "parsecomma" && op != "containsany" && op != "firstfail" && op != "firstempty" {
      write!(out, " {}", f[1]).unwrap();
    }
    out.push(' ');

    let result: Result<String, KataError> = (|| -> Result<String, KataError> {
      let mut r = String::new();
      // put(name, parser): replaces any previous parser of that name, prints its info
      macro_rules! put {
        ($name:expr, $c:expr) => {{
          let c: ConfigParser = $c;
          write!(r, "ok {}", info(&c)).unwrap();
          cfgs.insert($name.clone(), c);
        }};
      }
      macro_rules! cfg {
        ($name:expr) => {
          cfgs.get_mut(&$name).unwrap_or_else(|| panic!("script error line {}: no parser {}", lineno, $name))
        };
      }
      // A parser with the in-memory file reader installed (the oracle's real files).
      let fresh = |ko: &str, kfi: &str| -> ConfigParser {
        let mut c = ConfigParser::new(ko == "1", kfi == "1");
        c.set_include_reader(reader.clone());
        c
      };
      match op.as_str() {
        "file" => {
          let n = normalize(&f[1]).expect("script file path");
          files.borrow_mut().insert(n, f[2].clone());
          r.push_str("ok");
        }
        "newempty" => {
          put!(f[1], fresh(&f[2], &f[3]));
        }
        "new" => {
          let mut c = fresh(&f[2], &f[3]);
          c.initialize_in(&f[4])?;
          put!(f[1], c);
        }
        "newfile" => {
          let mut c = fresh(&f[2], &f[3]);
          c.initialize(&f[4])?;
          put!(f[1], c);
        }
        "newkvs" => {
          let mut c = ConfigParser::new_kvs(&parse_kvs(&f[2]))?;
          c.set_include_reader(reader.clone());
          put!(f[1], c);
        }
        "copy" => {
          let c = ConfigParser::new_copy(cfg!(f[2]))?;
          put!(f[1], c);
        }
        "init_in" => {
          cfg!(f[1]).initialize_in(&f[2])?;
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "init_file" => {
          cfg!(f[1]).initialize(&f[2])?;
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "init_kvs" => {
          cfg!(f[1]).initialize_kvs(&parse_kvs(&f[2]))?;
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "info" => {
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "getstring" => {
          write!(r, "ok {}", q(&cfg!(f[1]).get_string(&f[2])?)).unwrap();
        }
        "getstringp" => {
          write!(r, "ok {}", q(&cfg!(f[1]).get_string_possibles(&f[2], &to_set(&f[3]))?)).unwrap();
        }
        "getstrings" | "getstringsnet" | "getstringsp" => {
          let v: Vec<String> = if op == "getstrings" {
            cfg!(f[1]).get_strings(&f[2])?
          } else if op == "getstringsnet" {
            cfg!(f[1]).get_strings_non_empty_trim(&f[2])?
          } else {
            cfg!(f[1]).get_strings_possibles(&f[2], &to_set(&f[3]))?
          };
          write!(r, "ok {}", v.len()).unwrap();
          for s in v.iter() {
            write!(r, " {}", q(s)).unwrap();
          }
        }
        "getbool" => {
          write!(r, "ok {}", cfg!(f[1]).get_bool(&f[2])? as i32).unwrap();
        }
        "getbools" => {
          let v = cfg!(f[1]).get_bools(&f[2])?;
          write!(r, "ok {}", v.len()).unwrap();
          for b in v {
            write!(r, " {}", b as i32).unwrap();
          }
        }
        "getenabled" => {
          write!(r, "ok {}", cfg!(f[1]).get_enabled(&f[2])?.to_string()).unwrap();
        }
        "getint" => {
          write!(r, "ok {}", cfg!(f[1]).get_int(&f[2], parse_int(&f[3]), parse_int(&f[4]))?).unwrap();
        }
        "getints" => {
          let v = cfg!(f[1]).get_ints(&f[2], parse_int(&f[3]), parse_int(&f[4]))?;
          write!(r, "ok {}", v.len()).unwrap();
          for x in v {
            write!(r, " {}", x).unwrap();
          }
        }
        "getint64" => {
          write!(r, "ok {}", cfg!(f[1]).get_int64(&f[2], parse_int64(&f[3]), parse_int64(&f[4]))?).unwrap();
        }
        "getint64s" => {
          let v = cfg!(f[1]).get_int64s(&f[2], parse_int64(&f[3]), parse_int64(&f[4]))?;
          write!(r, "ok {}", v.len()).unwrap();
          for x in v {
            write!(r, " {}", x).unwrap();
          }
        }
        "getuint64" => {
          write!(r, "ok {}", cfg!(f[1]).get_uint64(&f[2], parse_uint64(&f[3]), parse_uint64(&f[4]))?).unwrap();
        }
        "getuint64s" => {
          let v = cfg!(f[1]).get_uint64s(&f[2], parse_uint64(&f[3]), parse_uint64(&f[4]))?;
          write!(r, "ok {}", v.len()).unwrap();
          for x in v {
            write!(r, " {}", x).unwrap();
          }
        }
        "getfloat" => {
          write!(r, "ok {}", fbits(cfg!(f[1]).get_float(&f[2], parse_float(&f[3]), parse_float(&f[4]))?)).unwrap();
        }
        "getfloats" => {
          let v = cfg!(f[1]).get_floats(&f[2], parse_float(&f[3]), parse_float(&f[4]))?;
          write!(r, "ok {}", v.len()).unwrap();
          for x in v {
            write!(r, " {}", fbits(x)).unwrap();
          }
        }
        "getdouble" => {
          write!(r, "ok {}", dbits(cfg!(f[1]).get_double(&f[2], parse_double(&f[3]), parse_double(&f[4]))?)).unwrap();
        }
        "getdoubles" => {
          let v = cfg!(f[1]).get_doubles(&f[2], parse_double(&f[3]), parse_double(&f[4]))?;
          write!(r, "ok {}", v.len()).unwrap();
          for x in v {
            write!(r, " {}", dbits(x)).unwrap();
          }
        }
        "getpairs" => {
          let v = cfg!(f[1]).get_non_negative_int_dashed_pairs(&f[2], parse_int(&f[3]), parse_int(&f[4]))?;
          write!(r, "ok {}", v.len()).unwrap();
          for p in v {
            write!(r, " ({},{})", p.0, p.1).unwrap();
          }
        }
        "contains" => {
          write!(r, "ok {}", cfg!(f[1]).contains(&f[2]) as i32).unwrap();
        }
        "containsany" => {
          write!(r, "ok {}", cfg!(f[1]).contains_any(&split_on(&f[2], ',')) as i32).unwrap();
        }
        "firstfail" => {
          write!(r, "ok {}", q(&cfg!(f[1]).first_found_or_fail(&split_on(&f[2], ','))?)).unwrap();
        }
        "firstempty" => {
          write!(r, "ok {}", q(&cfg!(f[1]).first_found_or_empty(&split_on(&f[2], ',')))).unwrap();
        }
        "overridekey" => {
          cfg!(f[1]).override_key(&f[2], &f[3]);
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "overridekeys" => {
          cfg!(f[1]).override_keys_newkvs(&parse_kvs(&f[2]));
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "overridekeysm" => {
          let mut sets: Vec<(BTreeSet<String>, BTreeSet<String>)> = Vec::new();
          for pr in split_on(&f[3], ';') {
            let ab = split_on(&pr, '|');
            sets.push((to_set(&ab[0]), to_set(if ab.len() > 1 { &ab[1] } else { "" })));
          }
          cfg!(f[1]).override_keys_newkvs_mutex_key_sets(&parse_kvs(&f[2]), &sets);
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "overridekeysfile" => {
          cfg!(f[1]).override_keys(&f[2])?;
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "parsecomma" => {
          let m = ConfigParser::parse_comma_separated(&f[1])?;
          write!(r, "ok {}", m.len()).unwrap();
          for (k, v) in m.iter() {
            write!(r, " {}={}", q(k), q(v)).unwrap();
          }
        }
        "markused" => {
          cfg!(f[1]).mark_key_used(&f[2]);
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "markprefix" => {
          cfg!(f[1]).mark_all_keys_used_with_prefix(&f[2]);
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "unsetused" => {
          cfg!(f[1]).unset_used_key(&f[2]);
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        "warn" => {
          let mut o = String::new();
          LOGGED.with(|l| l.borrow_mut().clear());
          cfg!(f[1]).warn_unused_keys(&mut o);
          // every message written to `out` was logged too, in the same order
          let logged: Vec<String> = LOGGED.with(|l| l.borrow().clone());
          let lines: Vec<String> = if o.is_empty() { Vec::new() } else { o[..o.len() - 1].split('\n').map(|x| x.to_string()).collect() };
          assert_eq!(logged, lines, "line {}: logged messages", lineno);
          write!(r, "ok {}", q(&o)).unwrap();
        }
        "alias" => {
          cfg!(f[1]).apply_alias(&f[2], &f[3])?;
          write!(r, "ok {}", info(cfg!(f[1]))).unwrap();
        }
        _ => panic!("script error line {}: unknown op {}", lineno, op),
      }
      Ok(r)
    })();

    match result {
      Ok(r) => out.push_str(&r),
      Err(e) => write!(out, "err {} {}", kind(&e), q(e.what())).unwrap(),
    }
    out.push('\n');
  }
  out
}

wasm_test! {
fn config_parser_vs_cpp() {
  let mut cases = Cases::new("config_parser::config_parser_vs_cpp");
  let script = fixture("oracle", "config_parser_ops.txt");
  let out = run(&script, &mut cases);
  let expected = fixture("oracle", "config_parser.txt");
  compare_lines("config_parser.txt", &out, &expected);
}
}

// Without an injected reader the file-reading paths fail like `FileUtils::open` on a missing file.
wasm_test! {
fn no_reader_means_missing_file() {
  let mut c = ConfigParser::new(false, true);
  let e = c.initialize("some/where.cfg").unwrap_err();
  assert!(matches!(e, KataError::IOError(_)));
  assert_eq!(e.what(), "Could not open file some/where.cfg - does not exist or invalid permissions?");
  let mut c = ConfigParser::new(false, true);
  let e = c.initialize_in("@include other.cfg\n").unwrap_err();
  assert_eq!(e.what(), "Could not open file other.cfg - does not exist or invalid permissions?");
  // a failed initialize leaves the parser uninitialized (upstream sets `initialized` last)
  assert!(c.initialize_in("a=1\n").is_ok());
  assert_eq!(c.get_all_key_vals(), "a = 1\n");
}
}
